function waveCountFor(players) {
  if (players <= 2) return 3;
  if (players <= 4) return 5;
  return 7;
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Positions (percent of viewport) + rotation for each player's bid circle,
