// ---------- Confetti burst (pure CSS/JS, no external libs) ----------
function Confetti({ legendary = false }) {
  const pieces = useMemo(() => {
    const count = legendary ? 60 : 32;
    const colors = ["#D4AF37", "#F2CB6B", "#2FA093", "#E8DCC0", "#A33E3E"];
    return Array.from({ length: count }, (_, i) => ({
      id: i,
      left: Math.random() * 100,
      delay: Math.random() * 0.5,
      duration: 1.5 + Math.random() * 1.3,
      rotate: Math.random() * 360,
      spin: 180 + Math.random() * 540,
      color: colors[Math.floor(Math.random() * colors.length)],
      w: 5 + Math.random() * 6,
      h: 8 + Math.random() * 8,
    }));
  }, [legendary]);
  return (
    <div style={styles.confettiWrap}>
      {pieces.map((p) => (
        <span
          key={p.id}
          style={{
            position: "absolute",
            top: "-14px",
            left: `${p.left}%`,
            width: p.w,
            height: p.h,
            background: p.color,
            opacity: 0.92,
            borderRadius: 1,
            transform: `rotate(${p.rotate}deg)`,
            animation: `confettiFall ${p.duration}s cubic-bezier(0.25,0.46,0.45,0.94) ${p.delay}s forwards`,
            "--spin": `${p.spin}deg`,
          }}
        />
      ))}
    </div>
  );
}

export default function App() {
  const [screen, setScreen] = useState("setup"); // setup | wave-intro | auction | reveal | wave-summary-step | wave-summary | final
  const [players, setPlayers] = useState([]);
  const [nameInput, setNameInput] = useState("");
  const [netWorth, setNetWorth] = useState({});
  const [wave, setWave] = useState(1);
  const [totalWaves, setTotalWaves] = useState(3);
  const [assetIndexInWave, setAssetIndexInWave] = useState(0);
  const [assetDeck, setAssetDeck] = useState([]);
  const [currentAsset, setCurrentAsset] = useState(null);
  const [bidders, setBidders] = useState({}); // name -> true if bidding
  const [timeLeft, setTimeLeft] = useState(10);
  const [timerActive, setTimerActive] = useState(false);
  const [lastResult, setLastResult] = useState(null);
  const [history, setHistory] = useState([]);
  const [celebrate, setCelebrate] = useState(null); // { legendary, id } drives confetti burst
  const timerRef = useRef(null);
  const waveAssetsRef = useRef([]);

  function addPlayer() {
    const n = nameInput.trim();
    if (!n || players.includes(n) || players.length >= 6) return;
    sfx.uiClick();
    setPlayers([...players, n]);
    setNetWorth({ ...netWorth, [n]: 0 });
    setNameInput("");
  }
  function removePlayer(n) {
    sfx.uiClick();
    setPlayers(players.filter((p) => p !== n));
  }

  function drawAssetPool(count) {
    // refill/reshuffle whenever we don't have enough left
    let pile = assetDeck;
    if (pile.length < count) pile = shuffle(ASSET_POOL);
    const drawn = pile.slice(0, count);
    setAssetDeck(pile.slice(count));
    return drawn;
  }

  function startGame() {
    sfx.gameStart();
    const tw = waveCountFor(players.length);
    setTotalWaves(tw);
    setWave(1);
    setAssetDeck(shuffle(ASSET_POOL));
    setScreen("wave-intro");
  }

  function beginWaveAuction() {
    sfx.uiClick();
    const drawn = drawAssetPool(5);
    waveAssetsRef.current = drawn;
    setAssetIndexInWave(0);
    setCurrentAsset(drawn[0]);
    setBidders({});
    setTimeLeft(10);
    setTimerActive(true);
    setScreen("auction");
  }

  function toggleBid(name) {
    if (!timerActive) return;
    setBidders((b) => {
      const next = { ...b };
      if (next[name]) {
        delete next[name];
        sfx.bidOff();
      } else {
        next[name] = true;
        sfx.bidOn();
      }
      return next;
    });
  }

  function stopTimerAndReveal() {
    setTimerActive(false);
    if (timerRef.current) clearInterval(timerRef.current);
    sfx.reveal();
    setScreen("reveal");
  }

  // countdown effect
  React.useEffect(() => {
    if (!timerActive) return;
    if (timeLeft <= 0) {
      stopTimerAndReveal();
      return;
    }
    timerRef.current = setTimeout(() => setTimeLeft((t) => t - 1), 1000);
    return () => clearTimeout(timerRef.current);
  }, [timerActive, timeLeft]);

  // tick sound each second the countdown ticks down (skip the initial reset value)
  React.useEffect(() => {
    if (!timerActive) return;
    if (timeLeft > 0 && timeLeft < 10) {
      (timeLeft <= 3 ? sfx.tickUrgent : sfx.tick)();
    }
  }, [timeLeft, timerActive]);

  // end the bidding window early once every player has placed a bid
  React.useEffect(() => {
    if (!timerActive) return;
    if (players.length > 0 && Object.keys(bidders).length >= players.length) {
      stopTimerAndReveal();
    }
  }, [bidders, timerActive, players.length]);

  function declareWinner(name) {
    const legendary = currentAsset.value >= 10;
    setNetWorth((nw) => ({ ...nw, [name]: (nw[name] || 0) + currentAsset.value }));
    setLastResult({ winner: name, asset: currentAsset, unclaimed: false });
    setHistory((h) => [...h, { wave, asset: currentAsset, winner: name, value: currentAsset.value }]);
    (legendary ? sfx.legendaryWin : sfx.win)();
    setCelebrate({ legendary, id: Date.now() });
    setScreen("wave-summary-step");
  }

  function declareUnclaimed() {
    sfx.unclaimed();
    setLastResult({ winner: null, asset: currentAsset, unclaimed: true });
    setScreen("wave-summary-step");
  }

  function nextAssetOrWaveEnd() {
    const nextIdx = assetIndexInWave + 1;
    const waveAssets = waveAssetsRef.current;
    if (nextIdx < waveAssets.length) {
      sfx.uiClick();
      setAssetIndexInWave(nextIdx);
      setCurrentAsset(waveAssets[nextIdx]);
      setBidders({});
      setTimeLeft(10);
      setTimerActive(true);
      setScreen("auction");
    } else {
      if (wave >= totalWaves) {
        sfx.gameOver();
        setCelebrate({ legendary: true, id: Date.now() });
        setScreen("final");
      } else {
        sfx.waveTransition();
        setScreen("wave-summary");
      }
    }
  }

  function nextWave() {
    sfx.uiClick();
    setWave((w) => w + 1);
    setScreen("wave-intro");
  }

  function resetGame() {
    sfx.uiClick();
    setPlayers([]);
    setNetWorth({});
    setWave(1);
    setAssetDeck([]);
    setHistory([]);
    setCelebrate(null);
    setScreen("setup");
  }

  const ranked = useMemo(
    () => [...players].sort((a, b) => (netWorth[b] || 0) - (netWorth[a] || 0)),
    [players, netWorth]
  );

  return (
    <div style={styles.appRoot}>
      <style>{`${FONT_IMPORT}
        * { box-sizing: border-box; }
        ::selection { background: #D4AF37; color: #0A0E17; }
        input:focus, button:focus-visible { outline: 2px solid #D4AF37; outline-offset: 2px; }
        @keyframes confettiFall {
          0% { transform: translateY(0) rotate(0deg); opacity: 0.95; }
          100% { transform: translateY(70vh) rotate(var(--spin)); opacity: 0; }
        }
        @keyframes urgentPulse {
          0%, 100% { transform: scale(1); }
          50% { transform: scale(1.08); }
        }
        @keyframes popIn {
          0% { transform: scale(0.85); opacity: 0; }
          100% { transform: scale(1); opacity: 1; }
        }
      `}</style>

      <div style={styles.vignette} />

      <div style={styles.stage}>
        <Header wave={wave} totalWaves={totalWaves} screen={screen} />

        {celebrate && <Confetti key={celebrate.id} legendary={celebrate.legendary} />}

        {screen === "setup" && (
          <SetupScreen
            players={players}
            nameInput={nameInput}
            setNameInput={setNameInput}
            addPlayer={addPlayer}
            removePlayer={removePlayer}
            startGame={startGame}
          />
        )}

        {screen === "wave-intro" && (
          <WaveIntro
            wave={wave}
            totalWaves={totalWaves}
            players={players}
            onStart={beginWaveAuction}
          />
        )}

        {screen === "auction" && currentAsset && (
          <AuctionScreen
            asset={currentAsset}
            index={assetIndexInWave}
            players={players}
            bidders={bidders}
            toggleBid={toggleBid}
            timeLeft={timeLeft}
            onTimeUp={stopTimerAndReveal}
          />
        )}

        {screen === "reveal" && currentAsset && (
          <RevealScreen
            asset={currentAsset}
            bidders={bidders}
            onDeclareWinner={declareWinner}
            onUnclaimed={declareUnclaimed}
          />
        )}

        {screen === "wave-summary-step" && lastResult && (
          <ResultScreen result={lastResult} netWorth={netWorth} players={players} onNext={nextAssetOrWaveEnd} />
        )}

        {screen === "wave-summary" && (
          <WaveSummary
            wave={wave}
            totalWaves={totalWaves}
            netWorth={netWorth}
            players={players}
            ranked={ranked}
            onNextWave={nextWave}
          />
        )}

        {screen === "final" && (
          <FinalScreen ranked={ranked} netWorth={netWorth} onReset={resetGame} />
        )}
      </div>
    </div>
  );
}

// ---------- Subcomponents ----------

function Header({ wave, totalWaves, screen }) {
  if (screen === "setup") return null;
  const dots = Array.from({ length: totalWaves }, (_, i) => i + 1);
  return (
    <div style={styles.header}>
      <div style={styles.headerTitle}>
        <AnkhIcon size={20} />
        <span style={styles.headerTitleText}>KANZ</span>
      </div>
      <div style={styles.waveDots}>
        {dots.map((d) => (
          <div key={d} style={{ opacity: d <= wave ? 1 : 0.28, transform: d === wave ? "scale(1.15)" : "scale(1)" }}>
            <AnkhIcon size={14} filled={d <= wave} />
          </div>
        ))}
      </div>
    </div>
  );
}

function SetupScreen({ players, nameInput, setNameInput, addPlayer, removePlayer, startGame }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>PASS-AND-PLAY · 2–6 PLAYERS</div>
      <h1 style={styles.h1}>KANZ</h1>
      <p style={styles.subtitle}>An auction of ancient treasures. Bid boldly. Spend wisely.</p>

      <div style={styles.divider} />

      <div style={styles.fieldRow}>
        <input
          style={styles.input}
          placeholder="Enter player name"
          value={nameInput}
          onChange={(e) => setNameInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && addPlayer()}
          maxLength={16}
        />
        <button style={styles.iconBtn} onClick={addPlayer} disabled={players.length >= 6}>
          <Plus size={18} color="#0A0E17" />
        </button>
      </div>

      <div style={styles.playerList}>
        {players.map((p, i) => (
          <div key={p} style={styles.playerChip}>
            <span style={styles.playerChipIndex}>{i + 1}</span>
            <span style={styles.playerChipName}>{p}</span>
            <button style={styles.chipRemove} onClick={() => removePlayer(p)}>
              <X size={14} color="#8A93A8" />
            </button>
          </div>
        ))}
        {players.length === 0 && <div style={styles.emptyHint}>Add at least 2 players to begin.</div>}
      </div>

      <button
        style={{ ...styles.primaryBtn, opacity: players.length >= 2 ? 1 : 0.4 }}
        disabled={players.length < 2}
        onClick={startGame}
      >
        <Play size={18} />
        Start Game
      </button>
      <div style={styles.hintSmall}>{players.length}/6 players · {players.length >= 2 ? `${waveCountFor(players.length)} waves this match` : "need 2+"}</div>
    </div>
  );
}

function WaveIntro({ wave, totalWaves, players, onStart }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>WAVE {wave} OF {totalWaves}</div>
      <h1 style={styles.h1}>Draw Your Hand</h1>
      <p style={styles.subtitle}>Each player draws 5 cards from the shared deck.</p>

      <div style={styles.instructionBox}>
        <div style={styles.instructionStep}>
          <span style={styles.stepNum}>1</span>
          <span>Shuffle the discard pile back in if the draw pile is short.</span>
        </div>
        <div style={styles.instructionStep}>
          <span style={styles.stepNum}>2</span>
          <span>Deal 5 cards face-down to each of the {players.length} players.</span>
        </div>
        <div style={styles.instructionStep}>
          <span style={styles.stepNum}>3</span>
          <span>Keep your hand hidden. When everyone's ready, begin the auction.</span>
        </div>
      </div>

      <button style={styles.primaryBtn} onClick={onStart}>
        <Sparkles size={18} />
        Start the Auction
      </button>
    </div>
  );
}

function AuctionScreen({ asset, index, players, bidders, toggleBid, timeLeft, onTimeUp }) {
  const tier = TIER_STYLE[asset.tier];
  const bidderCount = Object.keys(bidders).length;
  const pct = timeLeft / 10;
  const urgent = timeLeft <= 3;

  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>ASSET {index + 1} OF 5</div>

      <div style={{ ...styles.timerRing, borderColor: urgent ? "#A33E3E" : "#D4AF37", animation: urgent ? "urgentPulse 0.5s ease-in-out infinite" : "none" }}>
        <span style={{ ...styles.timerNum, color: urgent ? "#E86A6A" : "#F2CB6B" }}>{timeLeft}</span>
      </div>

      <div style={{ ...styles.assetCard, boxShadow: `0 0 60px ${tier.glow}`, borderColor: tier.color }}>
        <div style={{ ...styles.tierTag, background: tier.color }}>{tier.label.toUpperCase()}</div>
        {ASSET_IMAGES[asset.key] && (() => {
          const ratio = ASSET_IMAGE_RATIO[asset.key] || 0.75;
          const maxW = 220;
          const maxH = 240;
          // fit the frame to the image's real proportions, capped by the card's box
          const frameW = ratio >= maxW / maxH ? maxW : Math.round(maxH * ratio);
          const frameH = ratio >= maxW / maxH ? Math.round(maxW / ratio) : maxH;
          return (
            <div
              style={{
                ...styles.assetImgWrap,
                width: frameW,
                height: frameH,
                background: `radial-gradient(ellipse at center, ${tier.glow} 0%, #0D1220 70%)`,
              }}
            >
              <img src={ASSET_IMAGES[asset.key]} alt={asset.name} style={styles.assetImg} />
            </div>
          );
        })()}
        <div style={styles.assetName}>{asset.name}</div>
        <div style={styles.assetValueRow}>
          <AnkhIcon size={26} color="#F2CB6B" />
          <span style={styles.assetValue}>{asset.value}</span>
        </div>
      </div>

      <p style={styles.instructionLine}>
        Place your card face-down on the table now, then tap the circle on your side of the screen to confirm you're bidding — before the timer runs out.
      </p>

      {players.map((p, i) => {
        const active = !!bidders[p];
        const pos = bidCircleLayout(players.length)[i];
        return (
          <button
            key={p}
            onClick={() => toggleBid(p)}
            style={{
              ...styles.bidCircle,
              left: `${pos.x}%`,
              top: `${pos.y}%`,
              transform: `translate(-50%, -50%) rotate(${pos.rotate}deg)`,
              borderColor: active ? "#D4AF37" : "#2A3348",
              background: active ? "rgba(212,175,55,0.18)" : "rgba(19,27,46,0.92)",
              boxShadow: active ? "0 0 24px rgba(212,175,55,0.5)" : "0 4px 16px rgba(0,0,0,0.35)",
            }}
          >
            <span style={styles.bidCircleName}>{p}</span>
            <span style={{ ...styles.bidCircleStatus, color: active ? "#D4AF37" : "#4A5266" }}>
              {active ? "BIDDING ✓" : "TAP TO BID"}
            </span>
          </button>
        );
      })}

      <button style={styles.primaryBtn} onClick={onTimeUp}>
        <ChevronRight size={18} />
        {bidderCount > 0 ? "End Bidding Now" : "No One's Bid Yet — End Now"}
      </button>
    </div>
  );
}

function RevealScreen({ asset, bidders, onDeclareWinner, onUnclaimed }) {
  const names = Object.keys(bidders);
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>REVEAL</div>
      <h1 style={{ ...styles.h1, animation: "popIn 0.3s ease-out" }}>{asset.name}</h1>
      <p style={styles.subtitle}>
        {names.length === 0
          ? "No one bid on this asset."
          : "Everyone reveal your card on the table now. Tap whoever played the highest number."}
      </p>

      {names.length === 0 ? (
        <button style={styles.primaryBtn} onClick={onUnclaimed}>
          <ChevronRight size={18} />
          Continue — Unclaimed
        </button>
      ) : (
        <div style={styles.playerBidGrid}>
          {names.map((name) => (
            <button key={name} onClick={() => onDeclareWinner(name)} style={styles.winnerPickBtn}>
              <Crown size={18} color="#D4AF37" />
              <span style={styles.bidToggleName}>{name}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function ResultScreen({ result, netWorth, players, onNext }) {
  const { winner, asset, unclaimed } = result;
  return (
    <div style={styles.panel}>
      {unclaimed ? (
        <>
          <div style={styles.eyebrow}>UNCLAIMED</div>
          <h1 style={styles.h1}>{asset.name}</h1>
          <p style={styles.subtitle}>No one bid. The treasure is lost to the sands.</p>
        </>
      ) : (
        <>
          <div style={styles.eyebrow}>WINNER</div>
          <div style={{ ...styles.winnerBadge, animation: "popIn 0.35s ease-out" }}>
            <Trophy size={40} color="#D4AF37" />
          </div>
          <h1 style={{ ...styles.h1, animation: "popIn 0.35s ease-out" }}>{winner}</h1>
          <p style={styles.subtitle}>
            wins <strong style={{ color: "#F2CB6B" }}>{asset.name}</strong> worth {asset.value}
          </p>
        </>
      )}

      <div style={styles.netWorthList}>
        {players.map((p) => (
          <div key={p} style={styles.netWorthRow}>
            <span>{p}</span>
            <span style={styles.netWorthValue}>
              <AnkhIcon size={13} color="#8A93A8" />
              {netWorth[p] || 0}
            </span>
          </div>
        ))}
      </div>

      <button style={styles.primaryBtn} onClick={onNext}>
        <ChevronRight size={18} />
        Continue
      </button>
    </div>
  );
}

function WaveSummary({ wave, totalWaves, netWorth, players, ranked, onNextWave }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>WAVE {wave} COMPLETE</div>
      <h1 style={styles.h1}>Standings</h1>

      <div style={styles.standingsList}>
        {ranked.map((p, i) => (
          <div key={p} style={styles.standingsRow}>
            <span style={styles.standingsRank}>{i + 1}</span>
            <span style={styles.standingsName}>{p}</span>
            <span style={styles.standingsValue}>
              <AnkhIcon size={14} color="#D4AF37" />
              {netWorth[p] || 0}
            </span>
          </div>
        ))}
      </div>

      <p style={styles.subtitle}>Discard remaining hand cards. Fresh hands next wave.</p>

      <button style={styles.primaryBtn} onClick={onNextWave}>
        <ChevronRight size={18} />
        Begin Wave {wave + 1} of {totalWaves}
      </button>
    </div>
  );
}

function FinalScreen({ ranked, netWorth, onReset }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>MATCH COMPLETE</div>
      <div style={styles.winnerBadge}>
        <Crown size={48} color="#D4AF37" />
      </div>
      <h1 style={styles.h1}>{ranked[0]} Wins</h1>
      <p style={styles.subtitle}>Richest collector of the age.</p>

      <div style={styles.standingsList}>
        {ranked.map((p, i) => (
          <div key={p} style={{ ...styles.standingsRow, ...(i === 0 ? styles.standingsRowWinner : {}) }}>
            <span style={styles.standingsRank}>{i + 1}</span>
            <span style={styles.standingsName}>{p}</span>
            <span style={styles.standingsValue}>
              <AnkhIcon size={14} color={i === 0 ? "#0A0E17" : "#D4AF37"} />
              {netWorth[p] || 0}
            </span>
          </div>
        ))}
      </div>

      <button style={styles.primaryBtn} onClick={onReset}>
        <Sparkles size={18} />
        New Game
      </button>
    </div>
  );
}

